"""Mock certpin_vendor_sdk for testing."""
import hashlib


KNOWN_HOSTS = {
    "feed.certpin.dev": [
        "f155ea948d598ba3761566f5835f3e10153bc79aae6dbd67621bf378c14818b2",
    ],
}


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 hex fingerprint of a DER-encoded certificate."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Simple pin store that matches hosts against known fingerprints."""

    def __init__(self):
        self._pinned = dict(KNOWN_HOSTS)

    @classmethod
    def load(cls):
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        if host not in self._pinned:
            return False
        return fp in self._pinned[host]
